"""Archive M6 evidence without embedding temporary databases or credentials."""
from datetime import datetime, timezone
import hashlib
import json
from pathlib import Path
import subprocess
import xml.etree.ElementTree as ET

from inputs import source_manifest

ROOT = Path(__file__).resolve().parents[2]
OUT = ROOT / 'docs/reports/2026-09-10-runtime-v2-m6-results.json'
SDD = ROOT / '.superpowers/sdd/2026-09-10-runtime-v2-m6'


def artifact(path):
    data = path.read_bytes()
    entry = {'sha256': hashlib.sha256(data).hexdigest(), 'bytes': len(data)}
    if path.suffix == '.json':
        entry['data'] = json.loads(data)
        if path.name == 'coverage.json':
            coverage = entry['data']
            entry['data'] = {'meta': coverage['meta'], 'totals': coverage['totals'],
                             'files': {name: detail['summary'] for name, detail in coverage['files'].items()}}
            entry['archived_form'] = 'Totals and per-file summaries; sha256/bytes identify the full locally retained coverage report.'
    else:
        entry['text'] = data.decode()
    return entry


def case_summary(case):
    entry = dict(case.attrib)
    for key, value in list(entry.items()):
        if len(value) > 512:
            entry[key] = value[:512] + '…'
            entry[key + '_full_sha256'] = hashlib.sha256(value.encode()).hexdigest()
            entry[key + '_full_characters'] = len(value)
    entry['status'] = ('failed' if case.find('failure') is not None
                       else 'error' if case.find('error') is not None
                       else 'skipped' if case.find('skipped') is not None else 'passed')
    return entry


state = {
    'milestone': 'M6',
    'generated_at': datetime.now(timezone.utc).isoformat(),
    'baseline': 'c3037db829f34d3c30f12711042619d77deeddbe',
    'evidence_head': subprocess.check_output(['git', 'rev-parse', 'HEAD'], cwd=ROOT, text=True).strip(),
    'branch': 'refactor/runtime-v2',
    'input_sha256': source_manifest(ROOT),
    'artifacts': {},
    'junit': {},
    'visual_artifacts': {},
    'review_and_ledger': {},
    'limitations': [
        'Hosted CI is configured but was not executed.',
        'Telegram acceptance uses synthetic credentials and a local fixture peer; no real Telegram user was contacted.',
        'Browser acceptance explicitly uses the installed Chrome channel; ordinary startup does not install or launch a browser.',
        'The SDK-present offline suite skips the base-only missing-SDK test; fresh base-wheel acceptance executes it.',
        'Scheduled MCP admission/revocation binding remains deferred; schedule creation rejects MCP names.',
        'M4 follow-ups remain: duplicated receipt ceiling, inherited eight-second Docker fixture, generic maintenance error cause, unbenchmarked active-schedule scaling.',
        'The unchanged forty-case memory fixture is bounded regression evidence, not a general retrieval benchmark.',
        'M5 demonstrated that model prose can misnumber source citations; retrieval/marker/provenance checks do not establish universal answer accuracy.',
    ],
}
if OUT.exists():
    previous = json.loads(OUT.read_text())
    for key in ['delivery', 'cleanup', 'review_and_ledger']:
        if key in previous:
            state[key] = previous[key]

for directory in sorted((ROOT / 'test-results').glob('m6-*')):
    if not directory.is_dir():
        continue
    for path in sorted(directory.rglob('*')):
        if not path.is_file() or '__pycache__' in path.parts or 'htmlcov' in path.parts:
            continue
        relative = str(path.relative_to(ROOT))
        if path.suffix == '.xml' and path.name != 'coverage.xml':
            parsed = ET.parse(path).getroot()
            suites = [parsed] if parsed.tag == 'testsuite' else parsed.findall('testsuite')
            state['junit'][relative] = {
                'sha256': hashlib.sha256(path.read_bytes()).hexdigest(),
                'counts': {key: sum(int(suite.get(key, '0')) for suite in suites)
                           for key in ['tests', 'failures', 'errors', 'skipped']},
                'cases': [case_summary(case)
                          for suite in suites for case in suite.findall('testcase')],
            }
        elif path.suffix == '.png':
            data = path.read_bytes()
            state['visual_artifacts'][relative] = {'sha256': hashlib.sha256(data).hexdigest(), 'bytes': len(data)}
        elif path.suffix in {'.json', '.jsonl', '.txt', '.md', '.py', '.log', '.sh'}:
            # Daemon diagnostics stay local. Their index contains bounded hashes/errors.
            if path.name == 'daemon.log':
                continue
            state['artifacts'][relative] = artifact(path)

if SDD.exists():
    for path in sorted(SDD.iterdir()):
        if path.is_file() and path.suffix == '.md':
            state['review_and_ledger'][path.name] = artifact(path)
ledger = state['review_and_ledger'].get('progress.md', {}).get('text', '')
state['rulings'] = [line for line in ledger.splitlines() if 'Ruling:' in line]
OUT.write_text(json.dumps(state, indent=2) + '\n')
print(json.dumps({'path': str(OUT), 'bytes': OUT.stat().st_size,
                  'junit_reports': len(state['junit']), 'artifacts': len(state['artifacts']),
                  'rulings': len(state['rulings'])}))

