"""Hash actual tracked implementation inputs for acceptance provenance."""
import hashlib
from pathlib import Path
import subprocess


def source_manifest(repository: Path):
    paths = subprocess.check_output([
        'git', 'ls-files', '-z', 'src/hyperclaw', 'tests', 'scripts',
        'containers', 'examples', '.github', 'pyproject.toml', 'uv.lock', 'README.md', 'Makefile', 'pytest.ini',
    ], cwd=repository).decode().split('\0')
    return {name: hashlib.sha256((repository / name).read_bytes()).hexdigest()
            for name in sorted(paths) if name and (repository / name).is_file()}

